import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'package:trek_bikes_app/api_config.dart';
import 'package:trek_bikes_app/session_helper.dart';
class OrdersPage extends StatelessWidget { const OrdersPage({super.key}); Future<List<dynamic>> load()async{final t=await SessionHelper.accessToken;final r=await http.get(Uri.parse('${ApiConfig.baseUrl}/api/orders'),headers:{'Authorization':'Bearer $t'});return jsonDecode(r.body);} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Đơn hàng của tôi')),body:FutureBuilder<List<dynamic>>(future:load(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.map((x)=>ListTile(title:Text(x['orderCode']),subtitle:Text(x['status']),trailing:Text('${x['totalAmount']} đ'),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>OrderDetailPage(id:x['orderId']))))).toList());}));}
class OrderDetailPage extends StatelessWidget { const OrderDetailPage({super.key,required this.id}); final int id; Future<dynamic> load()async{final t=await SessionHelper.accessToken;final r=await http.get(Uri.parse('${ApiConfig.baseUrl}/api/orders/$id'),headers:{'Authorization':'Bearer $t'});return jsonDecode(r.body);} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Chi tiết đơn')),body:FutureBuilder<dynamic>(future:load(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final o=s.data;return ListView(children:[ListTile(title:Text(o['orderCode']),subtitle:Text(o['status'])),...(o['items'] as List).map((i)=>ListTile(title:Text(i['foodNameSnapshot']),trailing:Text('${i['quantity']} x ${i['unitPrice']}')))]);}));}
